from pathlib import Path
import json
root=Path('design')
def page(path,title,body):
 depth=len(Path(path).parts)-1; rel='../'*depth
 html=f'''<!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Jelly · {title}</title><link rel="icon" href="{rel}brand/logo/jelly-favicon.svg"><link rel="stylesheet" href="{rel}ui-kit/core.css"><link rel="stylesheet" href="{rel}motion/motion.css"><style>.hero{{padding:48px;background:var(--sidebar);border-radius:28px;margin-bottom:36px}}.hero h1{{font-size:clamp(32px,5vw,60px);max-width:750px}}.hero p{{max-width:600px;font-size:18px;color:var(--muted)}}.asset{{height:210px;object-fit:contain;width:100%;background:var(--surface);border-radius:16px;padding:20px;margin-bottom:14px}}.swatch{{height:72px;border-radius:12px;margin-bottom:12px;border:1px solid #7f91a9}}.avatar-grid{{display:grid;grid-template-columns:repeat(6,1fr);gap:20px;text-align:center}}.avatar-grid img{{width:110px;border-radius:50%}}.avatar-grid small{{display:block;text-transform:capitalize}}.tile{{text-decoration:none;color:var(--text);display:block}}.tile:hover{{border-color:var(--accent)}}@media(max-width:767px){{.hero{{padding:26px}}.avatar-grid{{grid-template-columns:repeat(3,1fr)}}}}</style></head><body><header class="docs-header"><a class="brand" href="{rel}index.html"><img src="{rel}brand/logo/jelly-mark.png" alt="">jelly</a><nav class="docs-nav" aria-label="Design kit"><a href="{rel}brand/index.html">Brand</a><a href="{rel}ui-kit/index.html">UI kit</a><a href="{rel}screens/index.html">Screens</a><a href="{rel}motion/index.html">Motion</a><a href="{rel}implementation/plan.md">Build plan</a></nav></header><main class="docs-main">{body}</main><footer class="docs-main wave"><small class="muted">Jelly design system · Familiar, with a little sea air. · September 2026</small></footer></body></html>'''
 (root/path).write_text(html)
page('index.html','Design library','''<section class="hero"><div class="eyebrow">The complete design reference</div><h1>Serious help.<br>A little personality.</h1><p>A friendly home for your agents. Clear conversations, effortless project switching, and small moments of delight.</p><div class="row wrap"><a class="btn primary" href="screens/index.html">Explore the screens</a><a class="btn" href="implementation/plan.md">Implementation plan</a></div></section><section class="grid-3"><a class="card tile" href="brand/index.html"><img class="asset" src="brand/logo/jelly-horizontal.svg" alt="Jelly brand"><h2>01 · Brand</h2><p class="muted">The approved Friendly bell, regular wordmark, colours, typography, voice, and twelve sea companions.</p></a><a class="card tile" href="ui-kit/index.html"><div class="asset" style="display:grid;place-items:center"><span class="badge good">Ready to help</span><span class="btn primary">Create agent</span></div><h2>02 · UI kit</h2><p class="muted">Shared tokens and components for light and dark, desktop and mobile.</p></a><a class="card tile" href="motion/index.html"><div class="asset" style="display:grid;place-items:center"><span class="jelly-working" data-state="working" style="width:90px;height:110px"><img src="brand/logo/jelly-mark.png" alt="Working jellyfish"></span></div><h2>03 · Motion</h2><p class="muted">Quiet working animation, purposeful transitions, reduced motion, and a tiny Easter egg.</p></a></section><section><div class="eyebrow">Product reference</div><h2>Every important moment has a home.</h2><p class="muted">40 screen scenarios, each available at desktop, tablet, and mobile widths, in light or dark. These are interactive fixtures; no user data or live agent is changed.</p><div class="grid-3"><a class="card tile" href="screens/index.html?screen=mobile-inbox">Mobile inbox →</a><a class="card tile" href="screens/index.html?screen=project-switcher">Fast project switching →</a><a class="card tile" href="screens/index.html?screen=folder-browser">Server folder selection →</a><a class="card tile" href="screens/index.html?screen=create-agent">Inherited working directory →</a><a class="card tile" href="screens/index.html?screen=waiting-sudo">Permission & handoff →</a><a class="card tile" href="screens/index.html?screen=dark-chat">Dark conversation →</a></div></section><section class="grid-2"><div class="card"><h2>Ready to build</h2><p><a href="README.md">Package guide</a> · <a href="DECISIONS.md">Design decisions</a></p><p><a href="specs/state-matrix.md">State matrix</a> · <a href="specs/flows.md">Interaction flows</a></p><p><a href="specs/accessibility.md">Accessibility</a> · <a href="implementation/verification.md">Verification record</a></p></div><div class="card"><h2>All the exploration, preserved</h2><p>The current app captures, three original directions, sea avatar collection, all six logos, and the earlier project concept are archived with their prompts.</p><a href="archive/README.md">Browse the archive →</a></div></section>''')
logos=[('jelly-horizontal.svg','Primary lockup'),('jelly-stacked.svg','Stacked lockup'),('jelly-inverse.svg','Inverse lockup'),('jelly-app-icon.svg','App icon'),('jelly-mark.png','Full-colour mark'),('jelly-monochrome.png','Single-colour mark')]
avatars=sorted((root/'brand/avatars').glob('*.png'))
page('brand/index.html','Brand kit','''<section class="hero"><div class="eyebrow">Friendly bell · Approved direction 05</div><h1>A friendly face.<br>An ordinary j.</h1><p>The jellyfish stands beside the wordmark. It brings warmth without getting in the way of your work.</p><a class="btn" href="brand-guidelines.md">Brand guidelines</a></section><section class="grid-3">'''+''.join(f'<div class="card"><img class="asset" src="logo/{f}" alt="{label}"><h3>{label}</h3><a href="logo/{f}" download>Download</a></div>' for f,label in logos)+'''</section><section class="grid-2"><div class="card"><h2>Leave room to float.</h2><p>Clear space: at least ¼ of the visible bell width on every side. Keep the standalone mark at least 24 px high; use the simplified mark below 32 px.</p><p>Use the regular Nunito 900 wordmark. Never replace the j with a creature.</p></div><div class="card"><h2>Friendly, never busy.</h2><p>White space first. Icy blue surfaces, readable navy type, one strong blue action. Sea details belong in identities, empty states, and quiet edges.</p><p>Use the dark lockup only on a dark surface. Never stretch, add a mouth, or put the mark behind message text.</p></div></section><section><h2>Twelve small companions.</h2><p class="muted">Choose an avatar for each agent. Keep names and status labels visible; a creature never carries meaning alone.</p><div class="avatar-grid">'''+''.join(f'<a href="avatars/{p.name}" download><img src="avatars/{p.name}" alt="{p.stem[3:].replace("-"," ")}"><small>{p.stem[3:].replace("-"," ")}</small></a>' for p in avatars)+'''</div></section><section><h2>Typography & voice</h2><div class="grid-2"><div class="card"><div style="font-family:'Jelly Nunito';font-weight:900;font-size:60px">jelly</div><p>Nunito 900 for the wordmark. Native system sans for the product. Monospace for paths, commands, and code.</p><a href="fonts/Nunito-Variable.ttf" download>Font</a> · <a href="fonts/OFL.txt">Font licence</a></div><div class="card"><h3>Warm, direct, useful.</h3><p>“Your draft is safe.”<br>“Choose a folder on the Jelly server.”<br>“Stopped by you.”</p><p class="muted">No sea puns in controls or errors. Tell people what happened and what they can do next.</p><a href="ASSETS.md">Asset provenance and production notes</a></div></div></section>''')
tokens=json.loads((root/'ui-kit/tokens.json').read_text())
page('ui-kit/index.html','UI kit','''<section class="hero"><div class="eyebrow">Reusable foundations</div><h1>Calm by default.<br>Clear in every state.</h1><p>Semantic colours, comfortable targets, rounded edges, and a reading area with room to breathe.</p><div class="row wrap"><a class="btn" href="tokens.json">Token source</a><a class="btn" href="components.md">Component specification</a><button class="btn" onclick="document.documentElement.dataset.theme=document.documentElement.dataset.theme==='dark'?'light':'dark'">Toggle light / dark</button></div></section><section><h2>Colour roles</h2><div class="grid-3">'''+''.join(f'<div class="card"><div class="swatch" style="background:var(--{name})"></div><strong>{name}</strong><p class="small muted">Semantic token · adapts to theme</p></div>' for name in ['page','sidebar','accent','text','selected','error'])+'''</div></section><section class="grid-2"><div class="card"><h2>Actions</h2><div class="row wrap"><button class="btn primary">Primary</button><button class="btn">Secondary</button><button class="btn quiet">Quiet</button><button class="btn danger">Delete</button><button class="btn primary" disabled>Disabled</button></div><p class="muted small" style="margin-top:16px">Specimens show hover, focus, active, and disabled styling. Tab through to inspect focus.</p></div><div class="card"><h2>Status</h2><div class="row wrap"><span class="badge good"><i class="dot"></i>Ready</span><span class="badge">Working</span><span class="badge warning">Needs you</span><span class="badge error">Failed</span><span class="badge">Interrupted</span></div><p class="small muted" style="margin-top:16px">Colour always accompanies a label. The same labels appear in sidebar and chat.</p></div><div class="card"><h2>Fields</h2><label class="field">Project name<input value="Website"><span class="hint">A short, recognisable name.</span></label><label class="field">Name required<input aria-invalid="true" aria-describedby="name-error"><span id="name-error" class="error-text">Give your project a name.</span></label><label class="field">Server folder<span class="path">/home/alex/work/website</span><span class="hint">Use the directory browser to select a folder.</span></label></div><div class="card"><h2>Notices & disclosure</h2><div class="stack"><div class="notice">Your draft is safe.</div><div class="notice warning">Milo needs your permission to continue.</div><div class="notice error">This folder can’t be opened. Try its parent folder.</div><details><summary>Tool activity · 3 files</summary><pre>Checked layout\nUpdated styles\nPreviewed mobile</pre></details></div></div></section><section class="card"><h2>Type & spacing</h2><div style="font-size:28px;line-height:1.2">A home for your agents.</div><h2 style="margin-top:18px">A warmer welcome.</h2><p>Body · 16 / 26. Comfortable reading at a maximum width of 720 px.</p><small class="muted">Metadata · 12 / 18. Always readable, never the only source of critical information.</small><hr class="rule"><p>Spacing: 4 · 8 · 12 · 16 · 20 · 24 · 32 · 40 · 48 · 64</p><p>Radii: 12 controls · 16 rows · 20 bubbles · 24 sheets · full pills</p><p>Targets: 44 × 44 minimum. Focus: 3 px ring, 3 px offset.</p></section><section><h2>Composed components</h2><div class="grid-3"><a class="card tile" href="../screens/index.html?screen=project-switcher">Project switcher →</a><a class="card tile" href="../screens/index.html?screen=avatar-picker">Avatar picker →</a><a class="card tile" href="../screens/index.html?screen=folder-browser">Folder browser →</a><a class="card tile" href="../screens/index.html?screen=working">Working indicator →</a><a class="card tile" href="../screens/index.html?screen=waiting-browser">Handoff card →</a><a class="card tile" href="../screens/index.html?screen=computer-ready">Computer panel →</a></div></section>''')
page('motion/index.html','Motion kit','''<section class="hero"><div class="eyebrow">Purpose before decoration</div><h1>A little life.<br>Never a distraction.</h1><p>Motion communicates ongoing work, preserves spatial context, and rewards curiosity once in a while.</p><a class="btn" href="README.md">Motion specification</a></section><section class="grid-2"><div class="card" id="demo"><h2>Working jellyfish</h2><div class="row" style="min-height:180px;justify-content:center"><span class="jelly-working" id="jelly" data-state="working" style="width:80px;height:100px"><img src="../brand/logo/jelly-mark.png" alt=""></span><div><strong id="status" role="status">Milo is working</strong><div class="muted small">Reviewing the homepage</div></div></div><div class="row wrap"><button class="btn primary" onclick="document.querySelector('#jelly').dataset.state='working';document.querySelector('#status').textContent='Milo is working'">Work</button><button class="btn" onclick="document.querySelector('#jelly').dataset.state='paused';document.querySelector('#status').textContent='Milo needs you'">Needs you</button><button class="btn" onclick="document.querySelector('#jelly').dataset.state='idle';document.querySelector('#status').textContent='Ready'">Ready</button></div><p><label><input type="checkbox" onchange="document.querySelector('#demo').dataset.reduced=this.checked"> Preview reduced motion</label></p></div><div class="card"><h2>Micro-interactions</h2><p class="muted">Replay discrete transitions. No looping decoration around the conversation.</p><div class="stack"><button class="btn" onclick="const x=document.querySelector('#sheet');x.classList.remove('sheet-enter');void x.offsetWidth;x.classList.add('sheet-enter')">Replay sheet entrance · 260 ms</button><div class="notice sheet-enter" id="sheet">Choose a project to continue.</div><button class="btn" onclick="this.classList.remove('avatar-bob');void this.offsetWidth;this.classList.add('avatar-bob')">A tiny hello · 280 ms</button></div></div></section><section class="card"><h2>Motion budget</h2><table><thead><tr><th>Moment</th><th>Timing</th><th>Reduced motion</th></tr></thead><tbody><tr><td>Press / hover</td><td>120 ms</td><td>Immediate colour change</td></tr><tr><td>Popover / message</td><td>180 ms</td><td>Immediate display</td></tr><tr><td>Sheet</td><td>260 ms</td><td>Immediate display</td></tr><tr><td>Working float</td><td>2,800 ms loop</td><td>Static mark + working label</td></tr><tr><td>Single faint bubble</td><td>4,800 ms loop, working only</td><td>Hidden</td></tr></tbody></table></section>''')
